installer-gui-script.script:
// An Ethernet controller supports AVB when it has a realtime transmit or
// receive queue, as IOEthernetController::getAVBSupport decides. Each
// enN interface's controller is asked, as matchingClass leaves out
// subclasses, which every driver's controller is.
function avbPort() {
    for (var unit = 0; unit < 64; unit++) {
        var interfaces = system.ioregistry.matchingName('en' + unit) || [];
        for (var index = 0; index < interfaces.length; index++) {
            var controllers = system.ioregistry.parentsOf(interfaces[index]) || [];
            for (var each = 0; each < controllers.length; each++) {
                var controller = controllers[each];
                if (controller['NumberOfRealtimeTransmitQueues'] > 0
                    || controller['NumberOfRealtimeReceiveQueues'] > 0) {
                    return true;
                }
            }
        }
    }
    my.result.type = 'Warn';
    my.result.title = 'No AVB Ethernet port found';
    my.result.message = 'Sending what plays to AVB speakers and amplifiers requires an AVB Ethernet port, '
        + 'and none was found. plaa plays everything else as usual.';
    return false;
}
